<?php
namespace App\Http\Controllers;
use App\Services\AuditLogger;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Gate;
use Inertia\Inertia;
class BroadcastController {
 public function __construct(private AuditLogger $audit) {}
 public function index(){Gate::authorize('synapse-users-moderate');$items=DB::table('broadcasts')->orderByDesc('id')->paginate(30);$items->getCollection()->transform(function($b){$b->total=DB::table('broadcast_recipients')->where('broadcast_id',$b->id)->count();$b->sent=DB::table('broadcast_recipients')->where('broadcast_id',$b->id)->where('status','sent')->count();return $b;});return Inertia::render('Broadcast/Index',['broadcasts'=>$items]);}
 public function store(Request $r){Gate::authorize('synapse-users-moderate');$data=$r->validate(['message'=>'required|string|max:4000','audience'=>'required|in:all,category,selected','activity_category'=>'nullable|in:heavy_active,active,low_active,dormant,suspicious','recipients'=>'nullable|array|max:5000','recipients.*'=>'string|max:255','throttle_ms'=>'required|integer|min:100|max:60000','max_retries'=>'required|integer|min:0|max:10','confirmed'=>'accepted']);$id=DB::table('broadcasts')->insertGetId(['message'=>$data['message'],'msgtype'=>'m.text','audience'=>$data['audience'],'activity_category'=>$data['activity_category']??null,'throttle_ms'=>$data['throttle_ms'],'max_retries'=>$data['max_retries'],'status'=>'queued','created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);$query=DB::table('user_activity')->select('user_id');if($data['audience']==='category')$query->where('category',$data['activity_category']);elseif($data['audience']==='selected')$query->whereIn('user_id',$data['recipients']??[]);$rows=$query->get();if($data['audience']==='selected'&&!count($rows)){DB::table('broadcasts')->where('id',$id)->delete();return back()->withErrors(['recipients'=>'حداقل یک گیرنده انتخاب کنید.']);}foreach($rows->chunk(500) as $chunk){DB::table('broadcast_recipients')->insert($chunk->map(fn($row)=>['broadcast_id'=>$id,'user_id'=>$row->user_id,'status'=>'pending','created_at'=>now(),'updated_at'=>now()])->all());}$this->audit->record($r,'broadcast.create','broadcast',(string)$id,['audience'=>$data['audience'],'activity_category'=>$data['activity_category']??null,'recipient_count'=>$rows->count(),'throttle_ms'=>$data['throttle_ms']]);return redirect()->route('broadcasts.index')->with('success','پیام در صف ارسال قرار گرفت.');}
 public function show(int $id){Gate::authorize('synapse-users-moderate');$broadcast=DB::table('broadcasts')->find($id);abort_unless($broadcast,404);$recipients=DB::table('broadcast_recipients')->where('broadcast_id',$id)->orderBy('id')->paginate(100);return Inertia::render('Broadcast/Show',['broadcast'=>$broadcast,'recipients'=>$recipients]);}
}
